learningSkills.find(s=>s.id==='stories').courses.unshift({id:'picture-adventures',title:'Make a little story happen',level:'Illustrated adventures',need:'Your child enjoys pictures and hands-on play, and benefits from seeing how actions connect.',goal:'Connect parts, objects and events through picture puzzles, visible plans, story building and shared narration.',props:'A grown-up, the child’s usual communication support, and optional familiar objects for acting out a story',notice:['Which picture details your child uses','Whether a visible model or fewer pieces helps','How your child shares a choice or part of a story'],home:'Choose one familiar daily event. Photograph or draw four moments, look through them together, and act out one part with real objects. Keep the pictures visible; pointing and AAC are welcome.',activities:Array.from({length:24},(_,index)=>({engine:'world',index}))});
